'use strict';
const FOOD_FLOW_UI7={bakeryView,bind};
function foodFlowPanel7(){const b=bakeryById5(selectedBakery5),s=state.stores.find(s=>s.id===foodStore5),last=state.foodFlow7.history.at(-1),result=last?.stores.find(x=>x.id===s?.id);return `<section class="card" style="margin-top:24px"><div class="card-head"><h2>Chytrý plán pekárny</h2>${b?`<button class="primary" id="foodSmartEdit7">Návrh denní výroby</button>`:''}</div><p class="sub">Skutečný prodej a chybějící kusy stejného dne v týdnu, čerstvé zásoby a známá sezóna. Limit odpadu je cíl, skutečný odpad ověří až provoz. Množství se řídí pracovní kapacitou, surovinami, penězi a prioritami kaváren.</p>${b?rows([['Pekárna',esc(b.name)],['Vedoucí návrhu',esc(b.manager?.name||'Zakladatel')],['Automatická množství',foodPolicy7(b.id).enabled?'Zapnutá':'Ruční odběry kaváren'],['Rozpočet tohoto plánu',money(foodPolicy7(b.id).budget)],['Cílový maximální odpad',number(foodPolicy7(b.id).maxWaste*100,0)+' %']]):'<p class="empty">Po spuštění vlastní pekárny nastav návrh a priority. Externí dodavatel dál používá ruční denní odběr.</p>'}${b&&last?.requests.some(r=>r.bakery===b.id)?`<button class="soft" id="foodSmartReport7">Otevřít návrh a skutečný výsledek</button>`:''}</section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Záchrana neprodaného jídla</h2>${s?'<button class="primary" id="foodRescueEdit7">Nastavit záchranu</button>':''}</div><p class="sub">Po běžném denním prodeji nabídni zbývající čerstvé kusy s odpolední slevou, v balíčku po dvou nebo je daruj. Prodej je omezen zásobou a příležitostmi mezi skutečně obslouženými hosty. Po trvanlivosti jídlo zůstává odpadem.</p>${s?rows([['Kavárna',esc(loc(s.id).name)],['Zvýhodněná nabídka',({none:'Vypnutá',discount:'Odpolední sleva',bundle:'Balíček dvou kusů'})[rescuePolicy7(s.id).mode]],['Darování zbývajících čerstvých kusů',rescuePolicy7(s.id).donate?'Povoleno · nejvýše 30 ks/den':'Vypnuto'],['Manipulace',money(.5)+'/kus · limit '+money(rescuePolicy7(s.id).budget)+'/týden']]):'<p class="empty">Vyber vlastní kavárnu.</p>'}${result?rows([['Běžný / zvýhodněný prodej',result.regular+' / '+result.rescued+' ks'],['Tržby zvýhodněné nabídky',money(result.rescueRevenue)],['Darováno · účetní cena zásob',result.donated+' ks · '+money(result.donationCost)],['Skutečná manipulace',money(result.handling)],['Zkažené jídlo',result.wasted+' ks · '+money(result.waste)]]):''}</section>`;}
bakeryView=function(){const html=FOOD_FLOW_UI7.bakeryView();return html+foodFlowPanel7();};
function foodSmartDialog7(){const b=bakeryById5(selectedBakery5),p=foodPolicy7(b.id),stores=state.stores.filter(s=>s.food5.source===b.id&&!s.franchise);show(`<h2>Plán výroby · ${esc(b.name)}</h2><div class="fields">${field('Historie · týdny',input('smartFoodWindow7',p.window,1,4))}${field('Bezpečnostní přídavek · %',input('smartFoodBuffer7',round(p.buffer*100),0,50))}${field('Cílový maximální odpad · %',input('smartFoodWaste7',round(p.maxWaste*100),0,50))}${field('Výrobní platby tohoto plánu / týden',input('smartFoodBudget7',p.budget,0,200000,1000))}</div><label class="checkbox-line"><input id="smartFoodEnabled7" type="checkbox" ${p.enabled?'checked':''}> Denní množství podle návrhu vedoucího</label><h3>Priority skutečných kaváren</h3>${stores.map(s=>field(loc(s.id).name,`<select data-food-priority7="${s.id}">${[1,2,3,4,5].map(n=>option(n,n+' · '+(n===5?'první':'priorita'),p.priorities.find(x=>x.id===s.id)?.rank||1)).join('')}</select>`)).join('')||'<p class="sub">Nejdřív nastav kavárně odběr z této pekárny.</p>'}<p class="sub">Při překročení cílového odpadu předchozího týdne další návrh vynechá bezpečnostní přídavek. Stávající provozní mandát pekárny, čtvrtletní výroba i hotovostní rezerva platí současně. Odhad bez historie používá ruční odběr. Nejde o záruku prodeje.</p><button class="primary" id="foodSmartPreview7">Prověřit denní návrh</button>`);el('foodSmartPreview7').onclick=()=>{try{const data={enabled:el('smartFoodEnabled7').checked,window:Number(el('smartFoodWindow7').value),buffer:Number(el('smartFoodBuffer7').value)/100,maxWaste:Number(el('smartFoodWaste7').value)/100,budget:Number(el('smartFoodBudget7').value),priorities:[...document.querySelectorAll('[data-food-priority7]')].map(x=>({id:x.dataset.foodPriority7,rank:Number(x.value)}))},q=foodProposal7(b.id,data);show(`<h2>Vedoucí navrhuje · ${esc(q.author)}</h2><p class="sub">První den následujícího skutečného týdne T${q.week}. Návrh dosud nic nevyrobil ani nezaplatil.</p><table class="data"><thead><tr><th>Kavárna / jídlo</th><th>Očekávaná poptávka</th><th>Čerstvá zásoba</th><th>Navržené kusy</th></tr></thead><tbody>${q.days.map(r=>`<tr><td>${esc(loc(r.store).name)} · ${r.category==='pastry'?'pečivo':'sendviče'}</td><td>${number(r.expected,1)}</td><td>${r.stock}</td><td>${r.qty}</td></tr>`).join('')}</tbody></table><p class="sub">Denní kapacita ${q.capacity} pracovních jednotek; skutečné kusy dále omezí receptury a rozpočet ${money(data.budget)}. ${q.days.map(r=>esc(r.reason)).slice(0,1).join('')}</p><div class="actions"><button class="primary" id="foodSmartConfirm7">Uložit mandát</button><button class="soft" id="foodSmartCancel7">Zrušit</button></div>`);el('foodSmartCancel7').onclick=()=>el('modal').close();el('foodSmartConfirm7').onclick=()=>{try{setFoodPolicy7(b.id,data,q);persist();render();el('modal').close();}catch(e){toast(e.message);}};}catch(e){toast(e.message);}};}
function foodSmartReport7(){const b=bakeryById5(selectedBakery5),h=state.foodFlow7.history.at(-1);if(!b||!h)return;show(`<h2>Výrobní plán · ${esc(b.name)} · T${h.week}</h2><p class="sub">Návrh je předem známý odhad. Prodej, zásoby a odpad jsou skutečné uzavřené výsledky.</p>${rows([['Výrobní platby plánu',money(h.paid[b.id]||0)],['Skutečně vyrobeno',b.last?.produced||0],['Skutečně odesláno',b.last?.delivered||0],['Prodej výrobního řetězce',b.last?.sold||0],['Skutečný odpis jídla/surovin',money(b.last?.waste||0)]])}<table class="data"><thead><tr><th>Den / kavárna / jídlo</th><th>Očekáváno</th><th>Virtuální zásoba</th><th>Objednáno</th></tr></thead><tbody>${h.requests.filter(r=>r.bakery===b.id).map(r=>`<tr><td>${['Po','Út','St','Čt','Pá','So'][r.day]} · ${esc(loc(r.store).name)} · ${r.category==='pastry'?'pečivo':'sendviče'}</td><td>${number(r.expected,1)}</td><td>${number(r.stock,1)}</td><td>${r.ordered}</td></tr>`).join('')}</tbody></table><p class="sub">Virtuální zásoba pro další dny odečítá očekávaný prodej. Fyzický prodej nepřepisuje předchozí návrh a nevzniká z odhadu.</p>`);}
function foodRescueDialog7(){const s=state.stores.find(s=>s.id===foodStore5),p=rescuePolicy7(s.id);show(`<h2>Záchrana jídla · ${esc(loc(s.id).name)}</h2><div class="fields">${field('Odpolední nabídka',`<select id="rescueMode7">${option('none','Bez zvýhodněného prodeje',p.mode)}${option('discount','Sleva na poslední kusy',p.mode)}${option('bundle','Balíček po dvou kusech',p.mode)}</select>`)}${field('Zvýhodnění ceny / %',input('rescueDiscount7',p.discount,15,60))}${field('Limit manipulace / týden',input('rescueBudget7',p.budget,0,10000,100))}</div><label class="checkbox-line"><input id="rescueDonate7" type="checkbox" ${p.donate?'checked':''}> Darovat zbývající čerstvé kusy před uzavřením</label><p class="sub">Jen kusy čerstvé tento den, které by do dalšího rána prošly trvanlivostí. Prodej či darování stojí 0,50 Kč manipulace za kus a musí se vejít i do odběrového a čtvrtletního rozpočtu. Darování má skutečný náklad zásoby; odměna pověsti vznikne až při fyzickém předání. Dva kusy balíčku se odečtou ze stejné zásoby.</p><button class="primary" id="rescueSave7">Uložit pravomoci</button>`);el('rescueSave7').onclick=()=>{try{setRescuePolicy7(s.id,{mode:el('rescueMode7').value,discount:Number(el('rescueDiscount7').value),budget:Number(el('rescueBudget7').value),donate:el('rescueDonate7').checked});persist();render();el('modal').close();}catch(e){toast(e.message);}};}
bind=function(){FOOD_FLOW_UI7.bind();if(el('foodSmartEdit7'))el('foodSmartEdit7').onclick=foodSmartDialog7;if(el('foodSmartReport7'))el('foodSmartReport7').onclick=foodSmartReport7;if(el('foodRescueEdit7'))el('foodRescueEdit7').onclick=foodRescueDialog7;};render();
